  vocab: [
    { fr: "Monument", en: "Monument", def: "Grosse unité d'aménagement (galley, toilettes, meuble de rangement, cloison équipée) construite en atelier et installée dans la cabine en une seule pièce.", tip: "Monumental : on ne le porte pas, on le roule." },
    { fr: "Galley", en: "Galley", def: "Cuisine de bord, aussi appelée office : meuble où l'on stocke, réchauffe et prépare le service des repas et boissons." },
    { fr: "Toilettes", en: "Lavatory", abbr: "LAV", def: "Cellule fermée livrée tout équipée : cuvette, lavabo, miroir, poubelle, détecteur de fumée." },
    { fr: "Insert de galley", en: "Galley insert", def: "Appareil amovible qu'on glisse dans un logement du galley et qui s'y branche : four, machine à boissons, bouilleur.", tip: "Insert = inséré : il entre et il sort." },
    { fr: "Chariot de service", en: "Trolley", def: "Meuble roulant aux dimensions standardisées, rangé sous le plan de travail et retenu par un verrou." },
    { fr: "Conteneur standard", en: "Standard unit", abbr: "SU", def: "Boîte de rangement amovible, à poignée, glissée dans un logement du galley." },
    { fr: "Verrou de retenue", en: "Retainer", def: "Loquet pivotant qui se rabat devant un chariot ou un conteneur pour l'empêcher de sortir de son logement." },
    { fr: "Panneau sandwich", en: "Honeycomb sandwich panel", def: "Panneau léger et rigide fait de deux peaux fines collées sur une âme en nid d'abeilles ; il craint les chocs ponctuels." },
    { fr: "Ferrure", en: "Fitting", def: "Pièce métallique de liaison qui accroche un élément (ici le pied du monument) à la structure ou à un rail." },
    { fr: "Bielle", en: "Tie rod", def: "Barre articulée à ses deux extrémités, souvent réglable en longueur, qui relie le haut d'un monument à la structure pour l'empêcher de basculer.", tip: "La ferrure porte, la bielle retient." },
    { fr: "Eau potable", en: "Potable water", def: "Eau propre stockée dans un réservoir de l'avion et distribuée sous pression aux robinets et aux machines." },
    { fr: "Eaux grises", en: "Grey water", def: "Eau qui a servi dans un évier ou un lavabo ; elle s'évacue par simple écoulement." },
    { fr: "Eaux usées", en: "Waste water", def: "Contenu des cuvettes, aspiré vers un réservoir fermé qu'on vide au sol." },
    { fr: "Mât de drainage", en: "Drain mast", def: "Petit profilé réchauffé, sous le fuselage, par lequel les eaux grises sont rejetées à l'extérieur." },
    { fr: "Toilettes à dépression", en: "Vacuum toilet", def: "Toilettes dont la cuvette est vidée par aspiration : une vanne s'ouvre sur une canalisation où la pression est plus basse que dans la cabine." },
    { fr: "Détecteur de fumée", en: "Smoke detector", def: "Capteur placé au plafond des toilettes qui alerte l'équipage en cas de fumée." },
    { fr: "Obturateur", en: "Blanking cap", def: "Bouchon ou capuchon qui ferme un raccord pendant le transport pour empêcher toute saleté d'y entrer ; on le retire au raccordement et on le compte." },
    { fr: "Point de manutention", en: "Handling point", def: "Endroit du monument prévu par son fabricant pour le saisir, le pousser ou le sangler sans l'abîmer." },
  ],

